alter table public.product_categories add column if not exists faq jsonb;
update public.product_categories c set faq = v.f from (values
('shyny', $j$[{"q": "Як дізнатися розмір шин для свого авто?", "a": "Розмір вказаний на боковині старої шини (наприклад, 205/55 R16), на наклейці в отворі водійських дверей або на кришці бензобака. Також можна скористатися блоком «Підбір за авто» на головній сторінці або зателефонувати нам."}, {"q": "Коли міняти літні шини на зимові?", "a": "Зимові шини варто ставити, коли середньодобова температура тримається нижче +7 °C, зазвичай це кінець жовтня – листопад. Літні повертають, коли тепло стабільно вище +7 °C."}, {"q": "Чи можна у вас одразу встановити шини?", "a": "Так. У Синельниковому працює наш цілодобовий шиномонтаж: можна купити шини й одразу поставити їх на авто."}, {"q": "Як отримати замовлення?", "a": "Самовивозом у Синельниковому (вул. Квітнева, 9) або доставкою Новою Поштою по всій Україні. Оплата при отриманні, карткою або на рахунок."}]$j$::jsonb),
('shyny-legkovi', $j$[{"q": "Що означають цифри 205/55 R16 91V?", "a": "205 — ширина шини в міліметрах, 55 — висота профілю у відсотках від ширини, R16 — посадковий діаметр диска в дюймах, 91 — індекс навантаження, V — індекс швидкості."}, {"q": "Яка мінімальна глибина протектора?", "a": "За ПДР для легкових авто — 1,6 мм. Для зимових шин бажано не менше 4 мм, бо з меншим протектором вони гірше тримають сніг і лід."}, {"q": "Чи можна ставити шини різних моделей на одну вісь?", "a": "Ні, на одній осі мають стояти однакові шини: той самий розмір, модель і сезон. Інакше авто поводиться непередбачувано під час гальмування."}, {"q": "Шини, яких немає в наявності, можна замовити?", "a": "Так. Товари з позначкою «під замовлення» привеземо, а точну ціну й термін менеджер підтвердить телефоном."}]$j$::jsonb),
('shyny-suv', $j$[{"q": "Чи можна ставити на кросовер звичайні легкові шини?", "a": "Можна, якщо збігається розмір і індекси навантаження та швидкості не нижчі, ніж рекомендує виробник авто. Шини SUV мають міцніший каркас і краще підходять для важких авто."}, {"q": "Що означають позначки AT і MT?", "a": "AT (All Terrain) — універсальні шини для асфальту й ґрунтових доріг. MT (Mud Terrain) — для бездоріжжя й бруду, вони шумніші на трасі."}, {"q": "Чи треба міняти всі чотири шини на повнопривідному авто?", "a": "Бажано так. Різний знос шин на повнопривідному авто навантажує трансмісію, тому краще ставити комплект однакових шин."}]$j$::jsonb),
('shyny-busy', $j$[{"q": "Що означає літера C у розмірі шини?", "a": "C (Commercial) — шина для легких вантажівок і бусів. Вона має посилений каркас і розрахована на більше навантаження, ніж звичайна легкова."}, {"q": "Чи можна поставити на бус легкові шини?", "a": "Не варто: легкова шина не розрахована на вагу завантаженого буса, швидше зношується і може пошкодитися. Обирайте шини з літерою C і потрібним індексом навантаження."}, {"q": "Який тиск тримати в шинах буса?", "a": "Тиск вказаний на наклейці на дверях або в інструкції до авто. Для завантаженого буса він зазвичай вищий, ніж для порожнього."}]$j$::jsonb),
('shyny-agro', $j$[{"q": "Які шини є в розділі «Агро / Спец»?", "a": "Шини для тракторів, сільгосптехніки, навантажувачів і спецтехніки. Якщо потрібного розміру немає на сайті, зателефонуйте: підберемо під замовлення."}, {"q": "Як прочитати розмір сільгосп-шини?", "a": "Наприклад, 9.5-32: 9.5 — ширина в дюймах, 32 — діаметр диска в дюймах. Також на шині вказана кількість шарів (PR) — що більше, то міцніша шина."}]$j$::jsonb),
('dysky', $j$[{"q": "Що означає PCD 5x112?", "a": "Це кількість кріпильних отворів (5) і діаметр кола, на якому вони розташовані (112 мм). PCD диска має точно збігатися з маточиною авто."}, {"q": "Що таке виліт (ET) диска?", "a": "ET — відстань від площини кріплення диска до його середини в міліметрах. Неправильний виліт може призвести до того, що колесо зачіпатиме підвіску чи арку."}, {"q": "Як підібрати диски на своє авто?", "a": "Потрібні PCD, діаметр центрального отвору (DIA), виліт ET і діаметр. Частину даних підкаже блок «Підбір за авто» на головній, або зателефонуйте — підберемо."}]$j$::jsonb),
('akumulyatory', $j$[{"q": "Як підібрати акумулятор для авто?", "a": "Важливі ємність (А·год), пусковий струм, розміри і полярність — з якого боку «плюс». Найпростіше подивитися дані старого акумулятора або скористатися блоком «Підбір за авто» на головній сторінці."}, {"q": "Що таке пряма і зворотна полярність?", "a": "Якщо дивитися на акумулятор з боку клем, при зворотній полярності «плюс» праворуч (так у більшості європейських авто), при прямій — ліворуч. Неправильна полярність означає, що дроти не дістануть до клем."}, {"q": "Скільки служить акумулятор?", "a": "Зазвичай 4–6 років. Термін скорочують короткі поїздки, сильні морози й повний розряд. Якщо авто погано заводиться зранку — час перевірити акумулятор."}, {"q": "Чи можна здати старий акумулятор?", "a": "Уточніть це телефоном у магазині: умови обміну старого акумулятора залежать від моделі й наявності."}]$j$::jsonb),
('avtozapchastyny-filtry', $j$[{"q": "Як часто міняти масляний фільтр?", "a": "Разом із моторною оливою: зазвичай кожні 8–15 тис. км або раз на рік, як рекомендує виробник авто."}, {"q": "Коли міняти повітряний і салонний фільтри?", "a": "Повітряний — приблизно кожні 15–30 тис. км, салонний — раз на рік або частіше, якщо в салоні з'явився неприємний запах чи пітніють скла."}, {"q": "Як знайти фільтр для свого авто?", "a": "Найточніше — за артикулом старого фільтра або за VIN-кодом. Введіть артикул у пошук на сайті або зателефонуйте нам."}]$j$::jsonb),
('masla-olyvy-ta-atf', $j$[{"q": "Як вибрати моторну оливу?", "a": "Дивіться в'язкість (наприклад, 5W-30) і допуски виробника авто — вони вказані в інструкції. Оливу з потрібним допуском можна знайти за назвою чи в'язкістю в пошуку."}, {"q": "Що таке ATF?", "a": "ATF — рідина для автоматичних коробок передач і гідропідсилювача керма. Тип ATF має відповідати вимогам виробника коробки."}, {"q": "Чи можна змішувати різні оливи?", "a": "Краще не змішувати. Якщо потрібно долити, а такої самої оливи немає, беріть оливу тієї ж в'язкості й з тими ж допусками."}]$j$::jsonb),
('avtozapchastyny-halmivna-systema', $j$[{"q": "Коли міняти гальмівні колодки?", "a": "Коли товщина накладки менше 2–3 мм, з'явився скрип чи скрегіт або збільшився гальмівний шлях. Зазвичай передні колодки служать 20–40 тис. км."}, {"q": "Чи треба міняти диски разом із колодками?", "a": "Не завжди. Диски міняють, якщо їхня товщина менша за мінімальну (вказана на диску) або на них є глибокі борозни чи биття."}, {"q": "Як підібрати гальмівні деталі?", "a": "За артикулом старої деталі або за маркою, моделлю й роком авто. Зателефонуйте — допоможемо підібрати."}]$j$::jsonb),
('avtozapchastyny-lampochky', $j$[{"q": "Як дізнатися, яка лампа потрібна?", "a": "Тип цоколя написаний на старій лампі (H4, H7, W5W тощо) або в інструкції до авто. Шукайте лампу за цим позначенням."}, {"q": "Чи можна ставити світлодіодні лампи замість звичайних?", "a": "У фари, розраховані на галогенні лампи, світлодіодні лампи можуть засліплювати зустрічних водіїв. Для габаритів і підсвітки салону світлодіоди підходять добре."}]$j$::jsonb),
('avtotovary-shchitky-skloochysnyka', $j$[{"q": "Як підібрати щітки склоочисника?", "a": "Потрібна довжина щітки (у мм або дюймах) для водійського і пасажирського боку та тип кріплення. Довжину можна виміряти на старій щітці."}, {"q": "Як часто міняти щітки?", "a": "Приблизно раз на 6–12 місяців або коли вони залишають смуги чи скриплять."}]$j$::jsonb),
('masla-okholodzhuyucha-ridyna', $j$[{"q": "Чи можна змішувати антифризи різних кольорів?", "a": "Колір не головне — важливий тип (G11, G12, G13). Змішувати різні типи не рекомендується: краще злити старий і залити один."}, {"q": "Як часто міняти охолоджуючу рідину?", "a": "Зазвичай кожні 2–5 років або 40–60 тис. км, залежно від типу рідини і вимог виробника авто."}]$j$::jsonb),
('avtozapchastyny-remeni', $j$[{"q": "Коли міняти ремінь ГРМ?", "a": "Термін вказує виробник, зазвичай кожні 60–120 тис. км. Обірваний ремінь ГРМ може пошкодити двигун, тому міняти його варто вчасно, разом із роликами."}, {"q": "Як підібрати ремінь?", "a": "За артикулом або маркуванням на старому ремені (наприклад, 6PK1200) чи за маркою й моделлю авто."}]$j$::jsonb),
('akumulyatory-zaryadni-prystroyi', $j$[{"q": "Який зарядний пристрій вибрати?", "a": "Для легкового авто підходить пристрій на 12 В зі струмом 4–10 А. Автоматичні зарядні самі вимикаються, коли акумулятор заряджений."}, {"q": "Чим пуско-зарядний відрізняється від звичайного?", "a": "Пуско-зарядний може не лише заряджати, а й допомогти завести авто з розрядженим акумулятором."}]$j$::jsonb),
('dysky-kovpaky', $j$[{"q": "Як підібрати ковпаки?", "a": "Ковпаки підбирають за діаметром сталевого диска: R13, R14, R15, R16. Діаметр вказаний на шині (наприклад, R15)."}]$j$::jsonb)
) v(s,f) where c.slug = v.s;
